                  31-60 <span data-testid="person-aged-31-60"><Fig>{aged.upTo60}</Fig></span>{' '}
                  61+ <span data-testid="person-aged-61"><Fig>{aged.over60}</Fig></span>
                </td>
                <td>
                  Overdue <span data-testid="person-overdue-count">{late.count}</span>{' '}
