471	      <BulkReassign sheetId={sheetId} user={user} selected={[...selected]} people={everyone}
472	        onDone={() => setSelected(new Set())} />
473	      <BulkRedate sheetId={sheetId} user={user} selected={[...selected]} onDone={() => setSelected(new Set())} />
474	      {people.isError && <p data-testid="people-error">The people could not be loaded.</p>}
475	      <table>
476	        <tbody>
477	          {sortPeople((people.data ?? []).filter((p) => showRetired || !p.retired), sortBy, (p) => dueOf.get(p.id) ?? null).map((p) => {
478	            const own = (claims.data ?? []).filter((c) => c.personId === p.id);
479	            const live = liveClaims(own, [p]);
480	            const claimed = sumAmounts(live.filter((c) => !correctsAnother(c)));
481	            const pct = byGrade.get(p.grade);
482	            const late = overdue(live, charges, (c) => claimDue(c, rates.data, (d) => gradeOn(p, d), floor, charges));
483	            const aged = agedDues(live, today, (c) => claimDue(c, rates.data, (d) => gradeOn(p, d), floor, charges));
484	            const split = splitDues(live, (c) => claimDue(c, rates.data, (d) => gradeOn(p, d), floor, charges));
485	            return (
486	              <tr key={p.id} data-testid={`person-row-${p.id}`}>
487	                <td>
488	                  <input type="checkbox" data-testid="person-select" checked={selectedPeople.has(p.id)}
489	                    onChange={(e) => selectPerson(p.id, e.target.checked)} />
490	                </td>
491	                <td>
492	                  <button type="button" data-testid="person-move-up" disabled={moving.isPending}
493	                    onClick={() => move(p.id, 'up')}>
494	                    Up
495	                  </button>{' '}
496	                  <button type="button" data-testid="person-move-down" disabled={moving.isPending}
497	                    onClick={() => move(p.id, 'down')}>
498	                    Down
499	                  </button>
500	                </td>
501	                <td data-testid="person-name">{p.name}</td>
502	                <td data-testid="person-grade">{p.grade}</td>
503	                <td>
504	                  <select data-testid="person-inline-grade" value={gradePicks[p.id] ?? p.grade}
505	                    onChange={(e) => {
506	                      setGradePicks((d) => ({ ...d, [p.id]: e.target.value }));
507	                      grading.reset();
508	                    }}>
509	                    {GRADES.map((g) => <option key={g} value={g}>{g}</option>)}
510	                  </select>{' '}
511	                  <button type="button" data-testid="person-inline-grade-save" disabled={grading.isPending}
512	                    onClick={() => grade(p)}>
513	                    Save grade
514	                  </button>
515	                </td>
516	                <td>
517	                  Active <span data-testid="person-active">{isActive(live, today) ? 'yes' : 'no'}</span>
518	                </td>
519	                <td>
520	                  Terms <span data-testid="person-terms">{p.terms ?? ''}</span>
521	                </td>
522	                <td>
523	                  Contact <span data-testid="person-contact">{p.contact ?? ''}</span>
524	                </td>
525	                <td>
526	                  Tags <span data-testid="person-tags">{showTags(p.tags)}</span>
527	                </td>
528	                <td>
529	                  From <span data-testid="person-origin">{p.origin ?? ''}</span>
530	                </td>
531	                <td>
532	                  Claimed <span data-testid="person-claimed"><Fig>{claimed}</Fig></span>
533	                </td>
534	                <td>
535	                  Due <span data-testid="person-due-total"><Fig>{showDue(personDue(live, rates.data, (d) => gradeOn(p, d), pct, floor, charges, cap))}</Fig></span>{' '}
536	                  excess <span data-testid="person-excess"><Fig>{excessOf(live, rates.data, (d) => gradeOn(p, d), pct, floor, charges, cap)}</Fig></span>
537	                </td>
538	                <td>
539	                  Cut <span data-testid="person-cut-total"><Fig>{personCutTotal(pools.data ?? [], p.id)}</Fig></span>
540	                </td>
541	                <td>
542	                  Settled <span data-testid="person-settled-total"><Fig>{split.settled}</Fig></span>{' '}
543	                  open <span data-testid="person-open-total"><Fig>{split.open}</Fig></span>
544	                </td>
545	                {(periods.data ?? []).map((q) => (
546	                  <td key={q.name}>
547	                    {q.name} <span data-testid={`person-period-${q.name}-due-total`}>
548	                      <Fig>{personPeriodDue(q, p, claims.data ?? [], people.data, rates.data, floor, charges)}</Fig></span>
549	                  </td>
550	                ))}
551	                <td>
552	                  Aged 0-30 <span data-testid="person-aged-0-30"><Fig>{aged.upTo30}</Fig></span>{' '}
553	                  31-60 <span data-testid="person-aged-31-60"><Fig>{aged.upTo60}</Fig></span>{' '}
554	                  61+ <span data-testid="person-aged-61"><Fig>{aged.over60}</Fig></span>
555	                </td>
556	                <td>
557	                  Overdue <span data-testid="person-overdue-count">{late.count}</span>{' '}
558	                  totalling <span data-testid="person-overdue-total"><Fig>{late.total}</Fig></span>
559	                </td>
560	                <td>
561	                  <button type="button" data-testid={`person-edit-${p.id}`} onClick={() => open(p)}>
562	                    Edit
563	                  </button>
564	                </td>
565	                <td>
566	                  <input type="date" data-testid="person-statement-asof" value={asOfDates[p.id] ?? ''}
567	                    onChange={(e) => {
568	                      setAsOfDates((d) => ({ ...d, [p.id]: e.target.value }));
569	                      statement.reset();
570	                    }} />{' '}
571	                  <button type="button" data-testid="person-statement" disabled={statement.isPending}
572	                    onClick={() => state(p.id)}>
573	                    Statement
574	                  </button>{' '}
575	                  <button type="button" data-testid="person-unstate" disabled={unstatement.isPending}
576	                    onClick={() => unstate(p.id)}>
577	                    Cancel statement
578	                  </button>{' '}
579	                  Statements <span data-testid="person-statement-count">{p.statementCount}</span>{' '}
580	                  last <span data-testid="person-stated-total"><Fig>{p.statedTotal ?? ''}</Fig></span>{' '}
581	                  on <span data-testid="person-statement-date">{p.statementDate ?? ''}</span>
582	                  {statement.isError && statement.variables?.id === p.id && (
583	                    <span data-testid="person-error">The statement could not be taken.</span>
584	                  )}
585	                  {unstatement.isError && unstatement.variables === p.id && (
586	                    <span data-testid="person-error">The statement could not be cancelled: only a steward can, and only a statement there is.</span>
587	                  )}
588	                  {watching.isError && watching.variables?.id === p.id && (
589	                    <span data-testid="person-error">The person could not be watched.</span>
590	                  )}
591	                  {retirement.isError && retirement.variables?.id === p.id && (
592	                    <span data-testid="person-error">The person could not be retired: the date must be a date.</span>
593	                  )}
594	                  {unretirement.isError && unretirement.variables === p.id && (
595	                    <span data-testid="person-error">The person could not be unretired: they are not retired.</span>
596	                  )}
597	                  {holding.isError && holding.variables?.id === p.id && (
598	                    <span data-testid="person-error">The person could not be held: the dates must be dates, the to-date not before the from-date.</span>
599	                  )}
600	                  {aliasing.isError && aliasing.variables?.id === p.id && (
601	                    <span data-testid="person-error">The alias could not be added: it needs to be given, and not be a name or alias already in use.</span>
602	                  )}
603	                  {merging.isError && merging.variables?.id === p.id && (
604	                    <span data-testid="person-error">The person could not be merged: only a steward can, into someone else, neither of them retired.</span>
605	                  )}
606	                  {moving.isError && moving.variables?.id === p.id && (
607	                    <span data-testid="person-error">The person could not be moved: the first cannot move up, nor the last down.</span>
608	                  )}
609	                  {grading.isError && grading.variables?.id === p.id && (
610	                    <span data-testid="person-error">The grade could not be saved: refused as the person form would refuse it, or someone else saved the person meanwhile.</span>
611	                  )}
612	                  {transferring.isError && transferring.variables?.id === p.id && (
613	                    <span data-testid="person-error">The person could not be transferred: only a steward can, not a retired person, to another sheet where their names match at most one person (not retired), and no one else has their contact.</span>
614	                  )}
615	                </td>
616	                <td>
617	                  Watched <span data-testid="person-watched">{watched.has(p.id) ? 'yes' : 'no'}</span>{' '}
618	                  <button type="button" data-testid="person-watch" disabled={watching.isPending || !watches.isSuccess}
619	                    onClick={() => watch(p.id, !watched.has(p.id))}>
620	                    {watched.has(p.id) ? 'Unwatch' : 'Watch'}
621	                  </button>
622	                </td>
623	                <td>
624	                  Retired <span data-testid="person-retired">{p.retired ? 'yes' : 'no'}</span>{' '}
625	                  from <span data-testid="person-retired-from">{p.retiredFrom ?? ''}</span>{' '}
626	                  <input type="date" data-testid="person-retire-date" value={retireDates[p.id] ?? ''}
627	                    onChange={(e) => {
628	                      setRetireDates((d) => ({ ...d, [p.id]: e.target.value }));
629	                      retirement.reset();
630	                    }} />{' '}
631	                  <button type="button" data-testid="person-retire" disabled={retirement.isPending}
632	                    onClick={() => retire(p.id)}>
633	                    Retire
634	                  </button>{' '}
635	                  <button type="button" data-testid="person-unretire" disabled={unretirement.isPending}
636	                    onClick={() => unretire(p.id)}>
637	                    Unretire
638	                  </button>{' '}
639	                  {p.retirements.map((r, i) => (
640	                    <Fragment key={i}><span data-testid="person-retirement-line">{r.from} to {r.to}</span>; </Fragment>
641	                  ))}
642	                  Snapshots{' '}
643	                  {p.snapshots.map((s, i) => (
644	                    <Fragment key={i}><span data-testid="person-snapshot-line">{s.day} {s.dueTotal}</span>; </Fragment>
645	                  ))}
646	                </td>
647	                <td>
648	                  On hold <span data-testid="person-hold">{p.held ? 'yes' : 'no'}</span>{' '}
649	                  {p.holds.map((h, i) => (
650	                    <span key={i} data-testid="person-hold-line">{h.from} to {h.to ?? '…'}; </span>
651	                  ))}
652	                  <input type="date" data-testid="person-hold-from" value={holdDates[p.id]?.from ?? ''}
653	                    onChange={(e) => changeHold(p.id, { from: e.target.value })} />{' '}
654	                  <input type="date" data-testid="person-hold-to" value={holdDates[p.id]?.to ?? ''}
655	                    onChange={(e) => changeHold(p.id, { to: e.target.value })} />{' '}
656	                  <button type="button" data-testid="person-hold-toggle" disabled={holding.isPending}
657	                    onClick={() => hold(p.id)}>
658	                    Hold
659	                  </button>
660	                </td>
661	                <td>
662	                  Clashing <span data-testid="person-clashing">{p.clashing ? 'yes' : 'no'}</span>
663	                </td>
664	                <td>
665	                  Aliases <span data-testid="person-aliases">{p.aliases.join(', ')}</span>{' '}
666	                  <input data-testid="person-alias-input" value={aliasInputs[p.id] ?? ''}
667	                    onChange={(e) => {
668	                      setAliasInputs((d) => ({ ...d, [p.id]: e.target.value }));
669	                      aliasing.reset();
670	                    }} />{' '}
671	                  <button type="button" data-testid="person-alias-add" disabled={aliasing.isPending}
672	                    onClick={() => alias(p.id)}>
673	                    Add alias
674	                  </button>
675	                </td>
676	                <td>
677	                  Patrons <span data-testid="person-patrons">
678	                    {patronShares(p.patronIds).map((s) => ({ name: nameOf.get(s.id) ?? '', share: s.share })).sort((x, y) => x.name.localeCompare(y.name)).map((s) => `${s.name} ${(s.share / 100).toFixed(2)}`).join(', ')}
679	                  </span>{' '}
680	                  backing <span data-testid="person-backing"><Fig>{backing(claims.data ?? [], p.patronIds, today)}</Fig></span>{' '}
681	                  <select data-testid="person-patron-select" value={patronPicks[p.id] ?? ''}
682	                    onChange={(e) => {
683	                      setPatronPicks((d) => ({ ...d, [p.id]: e.target.value }));
684	                      patronage.reset();
685	                    }}>
686	                    <option value="">Patron…</option>
687	                    {everyone.filter((q) => q.id !== p.id).map((q) => (
688	                      <option key={q.id} value={String(q.id)}>
689	                        {q.name}
690	                      </option>
691	                    ))}
692	                  </select>{' '}
693	                  <button type="button" data-testid="person-patron-add" disabled={patronage.isPending}
694	                    onClick={() => patronize(p.id)}>
695	                    Add patron
696	                  </button>
697	                  {patronage.isError && patronage.variables?.id === p.id && (
698	                    <span data-testid="person-patron-error">The patron could not be added: not themselves, nor one already named.</span>
699	                  )}
700	                </td>
701	                <td>
702	                  <select data-testid="person-merge-into" value={mergePicks[p.id] ?? ''}
703	                    onChange={(e) => {
704	                      setMergePicks((d) => ({ ...d, [p.id]: e.target.value }));
705	                      merging.reset();
706	                    }}>
707	                    <option value="">Merge into…</option>
708	                    {everyone.map((q) => (
709	                      <option key={q.id} value={String(q.id)}>
710	                        {q.name}
711	                      </option>
712	                    ))}
713	                  </select>{' '}
714	                  <button type="button" data-testid="person-merge" disabled={merging.isPending}
715	                    onClick={() => merge(p.id)}>
716	                    Merge
717	                  </button>{' '}
718	                  <input data-testid="person-transfer-to" placeholder="Sheet id" value={transferTos[p.id] ?? ''}
719	                    onChange={(e) => {
720	                      setTransferTos((d) => ({ ...d, [p.id]: e.target.value }));
721	                      transferring.reset();
722	                    }} />{' '}
723	                  <button type="button" data-testid="person-transfer" disabled={transferring.isPending}
724	                    onClick={() => transfer(p.id)}>
725	                    Transfer
726	                  </button>
727	                </td>
728	                <td>
729	                  <PersonPlans sheetId={sheetId} user={user} personId={p.id} />
730	                </td>
731	                <td>
732	                  <PersonClaims sheetId={sheetId} user={user} personId={p.id} claims={own} gradeOn={(d) => gradeOn(p, d)} rates={rates.data} floor={floor}
733	                    today={today} charges={charges} selected={selected} onSelect={select}
734	                    people={people.data ?? []} />
735	                </td>
736	              </tr>
737	            );
738	          })}
739	        </tbody>
740	      </table>
741	    </section>
742	  );
743	}
